    'RegistrationText'=>'已註冊的 SimpleRisk 實例會立即獲得升級和安全控制框架 (SCF) Extras 的訪問權限。 Upgrade Extra 提供了通過單擊按鈕來備份和升級您的 SimpleRisk 實例的能力。安全控制框架 (SCF) Extra 提供了一個集成到 SimpleRisk 治理功能中的通用控制框架。註冊 SimpleRisk 後，您的註冊信息將發送到 SimpleRisk 託管的服務器。所提供的註冊信息將由 SimpleRisk 用於通知客戶新版本和安全更新。註冊 SimpleRisk 的行為將使您選擇加入我們的營銷通訊，但您可以隨時使用這些通訊中的退訂鏈接選擇退出。 SimpleRisk 尊重我們客戶的隱私，通過 SimpleRisk 註冊過程提供給我們的信息絕不會出售給第三方。',
