    'CustomizationExtraDesc'              => '自訂附加功能允許新增和刪除不同類型的字段，並動態建立自訂頁面範本。',
    'NotificationExtraDesc'               => '郵件通知擴充功能使 SimpleRisk 能夠在風險提交、修改或進行其他操作時發送電子郵件通知。此擴充功能還可以添加為定時腳本，以便在風險準備好進行管理層審核時發送例行提醒。在 SimpleRisk Core 產品中，如果沒有此擴充功能，則不會向工具外部發送任何通知。',
    'VulnerabilityManagementExtraDesc'    => '漏洞管理附加功能可讓客戶將 SimpleRisk 執行個體與 Qualys、Tenable.io 或 Rapid7 Nexpose/InsightVM 集成，並將資產和漏洞資料匯入 SimpleRisk。之後，您可以選擇要覆蓋的站點，確定要匯入的漏洞評分，並對哪些漏洞進行分類以進行風險追蹤。',
    'IncidentManagementExtraDesc'         => '事件管理附加功能是基於 NIST 800-61 電腦安全事件處理指南，並提供來自 SimpleRisk 系統內部的事件管理功能。',

