    'SCFExtraDesc'                        => "安全控制框架 (SCF) Extra 是安全控制框架與 SimpleRisk 之間的直接整合。它將 SCF 的控制目錄及其在各種合規性和網路安全框架中的映射關係匯入 SimpleRisk 的治理功能，因此您可以採用所需的框架並管理其控制，而無需手動建置。",

